-- Enum existence checks are namespace-scoped (pg_type is not): a same-named enum
-- owned by a sibling module in a shared database must not suppress creation here.

-- Create repartition_document_type enum type
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE t.typname = 'repartition_document_type' AND n.nspname = 'public'
    ) THEN
        CREATE TYPE public.repartition_document_type AS ENUM ('invoice', 'refund');
    END IF;
END
$$;

-- Create repartition_type enum type
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE t.typname = 'repartition_type' AND n.nspname = 'public'
    ) THEN
        CREATE TYPE public.repartition_type AS ENUM ('base', 'tax');
    END IF;
END
$$;

CREATE SCHEMA IF NOT EXISTS tax;

CREATE TABLE IF NOT EXISTS tax.tax_repartition_lines (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL,
    template_id UUID NOT NULL,
    document_type repartition_document_type NOT NULL DEFAULT 'invoice',
    repartition_type repartition_type NOT NULL DEFAULT 'tax',
    factor_percent NUMERIC(16, 12) NOT NULL CHECK (factor_percent >= 0),
    account_id UUID,
    tag_ids UUID[] NOT NULL DEFAULT '{}',
    sort_order INTEGER NOT NULL DEFAULT 0,
    description TEXT,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_tax_repartition_lines_template_id_document_type_repartition_type_sort_order ON tax.tax_repartition_lines (template_id, document_type, repartition_type, sort_order);

-- Structural shape of a family line: base lines carry tags only (never an
-- account), and a zero factor is not a routing share.
ALTER TABLE tax.tax_repartition_lines
    ADD CONSTRAINT ck_tax_repartition_lines_base_has_no_account
    CHECK (repartition_type <> 'base' OR account_id IS NULL);
ALTER TABLE tax.tax_repartition_lines
    ADD CONSTRAINT ck_tax_repartition_lines_factor_nonzero
    CHECK (factor_percent <> 0);

-- Company fence (ADR-0014 strict): same predicate and policy names as every
-- other table in this schema; unset var sees zero rows.
ALTER TABLE tax.tax_repartition_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE tax.tax_repartition_lines FORCE  ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tax_repartition_lines_company_isolation ON tax.tax_repartition_lines;
CREATE POLICY tax_repartition_lines_company_isolation ON tax.tax_repartition_lines
