    USING      (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid)
    WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_tax_repartition_lines_metadata_gin ON tax.tax_repartition_lines USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_tax_repartition_lines_metadata_deleted_at ON tax.tax_repartition_lines ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_tax_repartition_lines_metadata_created_at ON tax.tax_repartition_lines ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_tax_repartition_lines_metadata_updated_at ON tax.tax_repartition_lines ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION tax.tax_repartition_lines_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS tax_repartition_lines_insert_audit ON tax.tax_repartition_lines;
CREATE TRIGGER tax_repartition_lines_insert_audit BEFORE INSERT ON tax.tax_repartition_lines
    FOR EACH ROW EXECUTE FUNCTION tax.tax_repartition_lines_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS tax_repartition_lines_update_audit ON tax.tax_repartition_lines;
CREATE TRIGGER tax_repartition_lines_update_audit BEFORE UPDATE ON tax.tax_repartition_lines
    FOR EACH ROW EXECUTE FUNCTION tax.tax_repartition_lines_audit_timestamp();

-- Inline foreign key constraints (forward + self refs)
ALTER TABLE tax.tax_repartition_lines ADD CONSTRAINT fk_tax_repartition_lines_template_id FOREIGN KEY (template_id) REFERENCES tax.tax_templates (id);
